{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2169-09-15 20:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee, one of the orthopedic doctors. I understand you fell earlier today and hurt your right knee?"
    },
    {
      "turn_number": 2,
      "time": "2169-09-15 20:16:00",
      "speaker": "Patient",
      "text": "Yes, I was just standing and my knee gave out. It’s been hurting a lot since then."
    },
    {
      "turn_number": 3,
      "time": "2169-09-15 20:17:00",
      "speaker": "Doctor",
      "text": "I see. We’ve reviewed your X-rays, and there’s a fracture near the top of your right tibia — that’s the larger bone in your lower leg."
    },
    {
      "turn_number": 4,
      "time": "2169-09-15 20:18:00",
      "speaker": "Patient",
      "text": "A fracture? But I didn’t fall that hard. Is it serious?"
    },
    {
      "turn_number": 5,
      "time": "2169-09-15 20:19:00",
      "speaker": "Doctor",
      "text": "It’s a comminuted fracture, which means the bone is broken into several pieces. Given your history of osteoarthritis and previous fractures, this makes sense. We’ll need surgery to fix it properly."
    },
    {
      "turn_number": 6,
      "time": "2169-09-15 20:20:00",
      "speaker": "Patient",
      "text": "Surgery? I’ve had surgeries before — I had a laminectomy years ago. I’m worried about infection again."
    },
    {
      "turn_number": 7,
      "time": "2169-09-15 20:21:00",
      "speaker": "Doctor",
      "text": "I understand your concern, especially with your past infection. We’ll take every precaution. The plan is to do an ORIF — that means open reduction and internal fixation — using a metal plate to stabilize the bone."
    },
    {
      "turn_number": 8,
      "time": "2169-09-15 20:22:00",
      "speaker": "Patient",
      "text": "Okay. Will I be able to walk after?"
    },
    {
      "turn_number": 9,
      "time": "2169-09-15 20:23:00",
      "speaker": "Doctor",
      "text": "Not right away. You’ll need to stay non-weight-bearing on that leg for several weeks. Physical therapy will help you regain strength later."
    },
    {
      "turn_number": 10,
      "time": "2169-09-15 20:24:00",
      "speaker": "Patient",
      "text": "Alright. And what about my other medicines? I take a lot for pain, asthma, and my HIV."
    },
    {
      "turn_number": 11,
      "time": "2169-09-15 20:25:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed all your medications. You’ll continue most of them. We’ll adjust pain meds around the surgery and make sure your HIV treatment isn’t interrupted."
    },
    {
      "turn_number": 12,
      "time": "2169-09-15 20:26:00",
      "speaker": "Patient",
      "text": "Good. I also get anxious before procedures. Can I talk to someone about that?"
    },
    {
      "turn_number": 13,
      "time": "2169-09-15 20:27:00",
      "speaker": "Doctor",
      "text": "Absolutely. Psychiatry can see you tomorrow if you'd like. We can also adjust your anxiety or depression meds if needed."
    },
    {
      "turn_number": 14,
      "time": "2169-09-15 20:28:00",
      "speaker": "Patient",
      "text": "That would help. Thank you."
    },
    {
      "turn_number": 15,
      "time": "2169-09-16 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs came back. Everything looks stable. Your kidney function is good, and your HIV is well-controlled."
    },
    {
      "turn_number": 16,
      "time": "2169-09-16 08:31:00",
      "speaker": "Patient",
      "text": "That’s good. What about the liver tests? I have hepatitis B and C."
    },
    {
      "turn_number": 17,
      "time": "2169-09-16 08:32:00",
      "speaker": "Doctor",
      "text": "Your liver enzymes are a bit elevated — AST is 101 — but we don’t think it’s acute. It’s likely related to your chronic hepatitis. We’ll monitor it."
    },
    {
      "turn_number": 18,
      "time": "2169-09-16 08:33:00",
      "speaker": "Patient",
      "text": "Okay. And my potassium was high yesterday, right?"
    },
    {
      "turn_number": 19,
      "time": "2169-09-16 08:34:00",
      "speaker": "Doctor",
      "text": "Yes, it was 7.0, which is concerning. But it corrected to 3.9 after treatment. We stopped your spironolactone temporarily and will watch it closely."
    },
    {
      "turn_number": 20,
      "time": "2169-09-16 08:35:00",
      "speaker": "Patient",
      "text": "I’ve had that happen before. I’m glad it’s down now."
    },
    {
      "turn_number": 21,
      "time": "2169-09-16 08:36:00",
      "speaker": "Doctor",
      "text": "We are too. Surgery is scheduled for tomorrow morning. We’ll go over consent later today."
    },
    {
      "turn_number": 22,
      "time": "2169-09-17 14:00:00",
      "speaker": "Doctor",
      "text": "Hi, you’re back from surgery. You did great. The ORIF was successful — the plate is in place and the bone is stable."
    },
    {
      "turn_number": 23,
      "time": "2169-09-17 14:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. My leg feels heavy, but not too painful right now."
    },
    {
      "turn_number": 24,
      "time": "2169-09-17 14:02:00",
      "speaker": "Doctor",
      "text": "We’ve got your pain well-controlled with hydromorphone and gabapentin. Chronic pain team will help adjust doses so you’re comfortable without over-sedation."
    },
    {
      "turn_number": 25,
      "time": "2169-09-17 14:03:00",
      "speaker": "Patient",
      "text": "I appreciate that. I’ve been on methadone for years — I don’t want to have withdrawal."
    },
    {
      "turn_number": 26,
      "time": "2169-09-17 14:04:00",
      "speaker": "Doctor",
      "text": "We’re continuing your methadone as scheduled. No changes there. Also, your blood pressure was high earlier, so we started metoprolol. It’s under control now."
    },
    {
      "turn_number": 27,
      "time": "2169-09-17 14:05:00",
      "speaker": "Patient",
      "text": "I’ve had BP issues before. Is that related to my heart?"
    },
    {
      "turn_number": 28,
      "time": "2169-09-17 14:06:00",
      "speaker": "Doctor",
      "text": "Your proBNP is 180, which is mildly elevated, but your heart rhythm is normal. We think it’s more related to your history of hypertension and obesity than heart failure."
    },
    {
      "turn_number": 29,
      "time": "2169-09-17 14:07:00",
      "speaker": "Patient",
      "text": "Okay. And my breathing? I sometimes feel short of breath."
    },
    {
      "turn_number": 30,
      "time": "2169-09-17 14:08:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray shows some mild volume overload, but no pneumonia. We’ll keep an eye on it. Your asthma is stable — keep using your inhalers as needed."
    },
    {
      "turn_number": 31,
      "time": "2169-09-18 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. The wound has some redness, but no pus or fever. We think it’s a hematoma — a blood collection — not an infection."
    },
    {
      "turn_number": 32,
      "time": "2169-09-18 09:01:00",
      "speaker": "Patient",
      "text": "But I’ve had infections before. Shouldn’t we treat it just in case?"
    },
    {
      "turn_number": 33,
      "time": "2169-09-18 09:02:00",
      "speaker": "Doctor",
      "text": "We’re being cautious. You’re starting a 7-day course of Keflex just to prevent any infection, even though we don’t think it’s infected now."
    },
    {
      "turn_number": 34,
      "time": "2169-09-18 09:03:00",
      "speaker": "Patient",
      "text": "That makes me feel better. What about my mood? I’ve been feeling down since I got here."
    },
    {
      "turn_number": 35,
      "time": "2169-09-18 09:04:00",
      "speaker": "Doctor",
      "text": "Psychiatry saw you yesterday. They’re increasing your duloxetine from 20mg to 30mg daily to help with depression and nerve pain."
    },
    {
      "turn_number": 36,
      "time": "2169-09-18 09:05:00",
      "speaker": "Patient",
      "text": "Thank you. That might help. I also get constipated easily."
    },
    {
      "turn_number": 37,
      "time": "2169-09-18 09:06:00",
      "speaker": "Doctor",
      "text": "We’ve added senna and docusate to your meds. Also, we’ll give you enoxaparin injections twice daily to prevent blood clots — that can cause constipation too."
    },
    {
      "turn_number": 38,
      "time": "2169-09-18 09:07:00",
      "speaker": "Patient",
      "text": "I remember those from last time. How long do I need them?"
    },
    {
      "turn_number": 39,
      "time": "2169-09-18 09:08:00",
      "speaker": "Doctor",
      "text": "For four weeks after surgery. Even when you’re at rehab, you’ll need to keep them up."
    },
    {
      "turn_number": 40,
      "time": "2169-09-19 10:00:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. The redness around the wound hasn’t worsened. We’re confident it’s healing well."
    },
    {
      "turn_number": 41,
      "time": "2169-09-19 10:01:00",
      "speaker": "Patient",
      "text": "And PT came by yesterday. They said I’m doing okay with transfers."
    },
    {
      "turn_number": 42,
      "time": "2169-09-19 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, great progress. You’re using the walker well. Keep wearing the knee immobilizer and don’t put any weight on the right leg."
    },
    {
      "turn_number": 43,
      "time": "2169-09-19 10:03:00",
      "speaker": "Patient",
      "text": "When will the staples come out?"
    },
    {
      "turn_number": 44,
      "time": "2169-09-19 10:04:00",
      "speaker": "Doctor",
      "text": "In about a week — on post-op day 14. We’ll do that at your follow-up."
    },
    {
      "turn_number": 45,
      "time": "2169-09-20 11:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. We’re planning to discharge you tomorrow to an extended care facility for rehab."
    },
    {
      "turn_number": 46,
      "time": "2169-09-20 11:01:00",
      "speaker": "Patient",
      "text": "Okay. Will I have all my meds with me?"
    },
    {
      "turn_number": 47,
      "time": "2169-09-20 11:02:00",
      "speaker": "Doctor",
      "text": "Yes. We’ve simplified some doses. Gabapentin is now 400mg every 8 hours, and you’ll stay on metoprolol, omeprazole, and your HIV meds."
    },
    {
      "turn_number": 48,
      "time": "2169-09-20 11:03:00",
      "speaker": "Patient",
      "text": "And the Keflex and enoxaparin?"
    },
    {
      "turn_number": 49,
      "time": "2169-09-20 11:04:00",
      "speaker": "Doctor",
      "text": "Finish the full 7-day course of Keflex. Enoxaparin continues for 4 weeks total — so about 3 more weeks after discharge."
    },
    {
      "turn_number": 50,
      "time": "2169-09-20 11:05:00",
      "speaker": "Patient",
      "text": "Got it. And if the wound gets worse?"
    },
    {
      "turn_number": 51,
      "time": "2169-09-20 11:06:00",
      "speaker": "Doctor",
      "text": "Call your doctor or go to the ER if you see increased redness, drainage, swelling, or if your temperature goes above 101.5."
    },
    {
      "turn_number": 52,
      "time": "2169-09-20 11:07:00",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 53,
      "time": "2169-09-21 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge. You’re stable, pain is controlled, and your wound is healing."
    },
    {
      "turn_number": 54,
      "time": "2169-09-21 09:01:00",
      "speaker": "Patient",
      "text": "I’m ready. It’s been a long few days."
    },
    {
      "turn_number": 55,
      "time": "2169-09-21 09:02:00",
      "speaker": "Doctor",
      "text": "It has. Keep following the non-weight-bearing rule, do your exercises, and attend all rehab sessions."
    },
    {
      "turn_number": 56,
      "time": "2169-09-21 09:03:00",
      "speaker": "Patient",
      "text": "I will. And I’ll keep taking my meds as listed."
    },
    {
      "turn_number": 57,
      "time": "2169-09-21 09:04:00",
      "speaker": "Doctor",
      "text": "Exactly. You’re doing great. Take care, and we’ll see you in follow-up."
    },
    {
      "turn_number": 58,
      "time": "2169-09-21 09:05:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 59,
      "time": "2169-09-21 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check-in before you leave. Any last questions?"
    },
    {
      "turn_number": 60,
      "time": "2169-09-21 10:01:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Wound care, meds, no weight on the leg, and when to call."
    },
    {
      "turn_number": 61,
      "time": "2169-09-21 10:02:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re all set. Get some rest at rehab and keep building your strength."
    },
    {
      "turn_number": 62,
      "time": "2169-09-21 10:03:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 63,
      "time": "2169-09-21 10:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care."
    },
    {
      "turn_number": 64,
      "time": "2169-09-21 10:05:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 65,
      "time": "2169-09-21 10:06:00",
      "speaker": "Doctor",
      "text": "Good luck."
    },
    {
      "turn_number": 66,
      "time": "2169-09-21 10:07:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    },
    {
      "turn_number": 67,
      "time": "2169-09-21 10:08:00",
      "speaker": "Doctor",
      "text": "See you soon."
    }
  ],
  "summary": {
    "admission_start": "2169-09-15 19:49:00",
    "admission_end": "2169-09-21 15:45:00",
    "summary_paragraph": "The patient was admitted after a fall that caused a right proximal tibia fracture. She underwent ORIF surgery and recovered well, with stable vital signs and controlled pain. Postoperatively, she developed mild wound redness attributed to hematoma, not infection, and was prescribed a short course of cephalexin as a precaution. Her chronic conditions, including HIV, hepatitis B and C, asthma, morbid obesity, and depression, remained stable. Blood pressure was managed with metoprolol, and psychiatric input led to an increase in duloxetine for mood and pain. She was transitioned to oral medications, prescribed enoxaparin for DVT prophylaxis, and discharged to extended care for rehabilitation with instructions to remain non-weight-bearing and complete her antibiotic and anticoagulant courses.",
    "problems": [
      "Closed fracture of upper end of tibia alone",
      "Hematoma complicating a procedure",
      "Viral hepatitis B without mention of hepatic coma, acute or unspecified, without mention of hepatitis delta",
      "Unspecified viral hepatitis C without hepatic coma",
      "Morbid obesity",
      "Asymptomatic human immunodeficiency virus [HIV] infection status",
      "Asthma, unspecified type, unspecified",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Chronic pain syndrome",
      "Anxiety state, unspecified",
      "Depressive disorder, not elsewhere classified",
      "Personal history of malignant neoplasm of ovary",
      "Other primary cardiomyopathies"
    ]
  }
}
